import type { BankQuestion } from "@/lib/bank";

/** Inverse Trigonometric Functions (Mathematics (JEE)): 119 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "math-inverse-trig-1", "question": "The principal value of cos⁻¹(−1/2) is:", "options": ["2π/3", "−π/3", "π/3", "4π/3"], "answer": 0, "explanation": "The principal range of cos⁻¹ is [0, π], and cos(2π/3) = −1/2. −π/3 lies outside [0, π], and 4π/3 is outside the range too.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-2", "question": "The value of tan⁻¹(√3) − sec⁻¹(−2) is:", "options": ["π", "π/3", "0", "−π/3"], "answer": 3, "explanation": "tan⁻¹√3 = π/3 and sec⁻¹(−2) = cos⁻¹(−1/2) = 2π/3, so the difference is π/3 − 2π/3 = −π/3.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-3", "question": "The domain of f(x) = sin⁻¹(2x − 1) is:", "options": ["[−1, 1]", "[0, 1]", "[−1, 0]", "[0, 1/2]"], "answer": 1, "explanation": "We need −1 ≤ 2x − 1 ≤ 1, i.e. 0 ≤ 2x ≤ 2, i.e. 0 ≤ x ≤ 1.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-4", "question": "The value of sin(2 tan⁻¹(1/2)) is:", "options": ["3/5", "4/5", "1", "2/5"], "answer": 1, "explanation": "sin 2θ = 2 tan θ/(1 + tan²θ) = (2 × 1/2)/(1 + 1/4) = 1/(5/4) = 4/5. 3/5 is cos 2θ.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-5", "question": "The value of sin⁻¹(sin(2π/3)) is:", "options": ["2π/3", "−π/3", "π/6", "π/3"], "answer": 3, "explanation": "2π/3 is outside [−π/2, π/2]. Since sin(2π/3) = sin(π − 2π/3) = sin(π/3) and π/3 is in the principal range, the value is π/3.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-6", "question": "The value of cos⁻¹(cos(7π/6)) is:", "options": ["5π/6", "7π/6", "π/6", "−5π/6"], "answer": 0, "explanation": "7π/6 is outside [0, π]. cos(7π/6) = cos(2π − 7π/6) = cos(5π/6), and 5π/6 lies in [0, π].", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-7", "question": "If sin⁻¹x + sin⁻¹y = 2π/3, then cos⁻¹x + cos⁻¹y equals:", "options": ["2π/3", "π/6", "π/3", "π"], "answer": 2, "explanation": "cos⁻¹x = π/2 − sin⁻¹x for every x in [−1, 1], so the sum is π − (sin⁻¹x + sin⁻¹y) = π − 2π/3 = π/3.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-8", "question": "The value of tan⁻¹1 + tan⁻¹2 + tan⁻¹3 is:", "options": ["π/2", "3π/4", "0", "π"], "answer": 3, "explanation": "Since 2 × 3 > 1, tan⁻¹2 + tan⁻¹3 = π + tan⁻¹((2 + 3)/(1 − 6)) = π + tan⁻¹(−1) = 3π/4. Adding tan⁻¹1 = π/4 gives π.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-9", "question": "The value of 2 tan⁻¹(1/3) + tan⁻¹(1/7) is:", "options": ["π/3", "π/4", "π/2", "π/6"], "answer": 1, "explanation": "2 tan⁻¹(1/3) = tan⁻¹((2/3)/(1 − 1/9)) = tan⁻¹(3/4). Then tan⁻¹(3/4) + tan⁻¹(1/7) = tan⁻¹((3/4 + 1/7)/(1 − 3/28)) = tan⁻¹((25/28)/(25/28)) = tan⁻¹1 = π/4.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-10", "question": "The solution set of tan⁻¹(2x) + tan⁻¹(3x) = π/4 is:", "options": ["{−1}", "{1/6, −1}", "{1/6}", "{1/3}"], "answer": 2, "explanation": "Taking tan: 5x/(1 − 6x²) = 1, so 6x² + 5x − 1 = 0, x = 1/6 or −1. For x = −1 the left side is tan⁻¹(−2) + tan⁻¹(−3) = −3π/4, not π/4, so only x = 1/6 survives.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "math-inverse-trig-11", "question": "The range of f(x) = sin⁻¹x + cos⁻¹x + tan⁻¹x is:", "options": ["[π/4, 3π/4]", "[0, π]", "(−π/2, π/2)", "[π/2, π]"], "answer": 0, "explanation": "The domain is [−1, 1] and sin⁻¹x + cos⁻¹x = π/2 there. tan⁻¹x runs over [−π/4, π/4], so f runs over [π/4, 3π/4].", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-12", "question": "The value of cos⁻¹(cos 10) (10 in radians) is:", "options": ["10 − 3π", "4π − 10", "10 − 4π", "3π − 10"], "answer": 1, "explanation": "3π ≈ 9.42 < 10 < 4π ≈ 12.57. Then 4π − 10 ≈ 2.57 lies in [0, π] and cos(4π − 10) = cos 10, so the value is 4π − 10. 10 − 3π ≈ 0.58 is also in [0, π] but cos(10 − 3π) = −cos 10.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-13", "question": "For real x, cos(tan⁻¹(sin(cot⁻¹x))) equals:", "options": ["√((x² + 2)/(x² + 1))", "1/√(x² + 2)", "√((x² + 1)/(x² + 2))", "x/√(x² + 2)"], "answer": 2, "explanation": "Let cot⁻¹x = θ, so sin θ = 1/√(1 + x²). Let tan⁻¹(1/√(1 + x²)) = φ; then cos φ = 1/√(1 + 1/(1 + x²)) = √((1 + x²)/(2 + x²)).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-14", "question": "The solutions of tan⁻¹((x − 1)/(x − 2)) + tan⁻¹((x + 1)/(x + 2)) = π/4 are:", "options": ["x = ±1/√2", "x = 1/√2 only", "x = ±1/2", "x = ±√(7/2)"], "answer": 0, "explanation": "Taking tan: [(x − 1)(x + 2) + (x + 1)(x − 2)]/[(x² − 4) − (x² − 1)] = (2x² − 4)/(−3) = 1, so x² = 1/2. At x² = 1/2 the product of the two arguments is (x² − 1)/(x² − 4) = 1/7 < 1, so the addition formula holds and both roots are valid.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "math-inverse-trig-15", "question": "For |x| < 1/√3, d/dx [tan⁻¹((3x − x³)/(1 − 3x²))] equals:", "options": ["1/(1 + x²)", "−3/(1 + x²)", "3/(1 − x²)", "3/(1 + x²)"], "answer": 3, "explanation": "Put x = tan θ with |θ| < π/6; the argument is tan 3θ and 3θ ∈ (−π/2, π/2), so the function equals 3θ = 3 tan⁻¹x. Its derivative is 3/(1 + x²).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-16", "question": "The value of tan(2 tan⁻¹(1/5) − π/4) is:", "options": ["7/17", "17/7", "−7/17", "−17/7"], "answer": 2, "explanation": "2 tan⁻¹(1/5) = tan⁻¹((2/5)/(24/25)) = tan⁻¹(5/12). Then tan(A − π/4) = (5/12 − 1)/(1 + 5/12) = (−7/12)/(17/12) = −7/17.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-17", "question": "The domain of f(x) = sin⁻¹((x − 3)/2) − log₁₀(4 − x) is:", "options": ["[1, 4)", "[1, 5]", "(1, 4)", "[2, 4)"], "answer": 0, "explanation": "sin⁻¹ needs −1 ≤ (x − 3)/2 ≤ 1, i.e. 1 ≤ x ≤ 5; the logarithm needs 4 − x > 0, i.e. x < 4. Together: [1, 4).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-18", "question": "If cos⁻¹x − cos⁻¹(y/2) = α, then 4x² − 4xy cos α + y² equals:", "options": ["2 sin 2α", "−4 sin²α", "4", "4 sin²α"], "answer": 3, "explanation": "cos α = x(y/2) + √(1 − x²)√(1 − y²/4). Isolate the root and square: (cos α − xy/2)² = (1 − x²)(1 − y²/4). Expanding gives x² + y²/4 − xy cos α = sin²α; multiply by 4.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "math-inverse-trig-19", "question": "The value of cot(Σ (k = 1 to 10) cot⁻¹(2k²)) is:", "options": ["10/11", "11/10", "21/19", "19/21"], "answer": 1, "explanation": "cot⁻¹(2k²) = tan⁻¹(1/(2k²)) = tan⁻¹(2/(4k²)) = tan⁻¹[((2k + 1) − (2k − 1))/(1 + (2k + 1)(2k − 1))] = tan⁻¹(2k + 1) − tan⁻¹(2k − 1). The sum telescopes to tan⁻¹21 − tan⁻¹1 = tan⁻¹(20/22) = tan⁻¹(10/11), whose cotangent is 11/10.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "math-inverse-trig-20", "question": "Consider (principal values throughout):\n(1) sin⁻¹(−x) = −sin⁻¹x for x ∈ [−1, 1].\n(2) cos⁻¹(−x) = −cos⁻¹x for x ∈ [−1, 1].\n(3) tan⁻¹x + tan⁻¹(1/x) = π/2 for every x ≠ 0.\n(4) sec⁻¹x = cos⁻¹(1/x) for |x| ≥ 1.\nHow many of these statements are correct?", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(1) True: sin⁻¹ is odd. (2) False: cos⁻¹(−x) = π − cos⁻¹x. (3) False: for x < 0 the sum is −π/2. (4) True. Two are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-21", "question": "If sin⁻¹x + sin⁻¹(2x) = π/3, then x equals:", "options": ["√(3/7)", "1/√28", "−√(3/28)", "√(3/28)"], "answer": 3, "explanation": "sin⁻¹(2x) = π/3 − sin⁻¹x. Taking sine: 2x = (√3/2)√(1 − x²) − x/2, so 5x = √3√(1 − x²) with x > 0. Squaring: 25x² = 3 − 3x², x² = 3/28, x = √(3/28) (then 2x = √(3/7) ≤ 1, so it is admissible). The negative root fails the sign condition.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-22", "question": "lim (x → 0) (sin⁻¹x − tan⁻¹x)/x³ equals:", "options": ["1/2", "1/6", "−1/2", "1/3"], "answer": 0, "explanation": "sin⁻¹x = x + x³/6 + … and tan⁻¹x = x − x³/3 + …, so the difference is x³/6 + x³/3 = x³/2 + …, and the limit is 1/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-23", "question": "Let [·] denote the greatest integer function. The set of all x for which [sin⁻¹x] > [cos⁻¹x] is:", "options": ["(cos 1, 1]", "[1/√2, 1]", "[sin 1, 1]", "(sin 1, 1]"], "answer": 2, "explanation": "[sin⁻¹x] ∈ {−2, −1, 0, 1} and [cos⁻¹x] ≥ 0, so we need [sin⁻¹x] = 1, i.e. sin⁻¹x ≥ 1, i.e. x ≥ sin 1. Then cos⁻¹x = π/2 − sin⁻¹x ≤ π/2 − 1 < 1, so [cos⁻¹x] = 0 < 1. For x < sin 1, [sin⁻¹x] ≤ 0 ≤ [cos⁻¹x]. Hence x ∈ [sin 1, 1].", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-inverse-trig-24", "question": "For 0 < x < 1, if 2 sin⁻¹(2x/(1 + x²)) − cos⁻¹((1 − x²)/(1 + x²)) + tan⁻¹(2x/(1 − x²)) = π/2, then x equals:", "options": ["1/√3", "√3", "√2 + 1", "√2 − 1"], "answer": 3, "explanation": "Put x = tan t with 0 < t < π/4. Then each of sin⁻¹(2x/(1 + x²)), cos⁻¹((1 − x²)/(1 + x²)) and tan⁻¹(2x/(1 − x²)) equals 2t, so the equation is 4t − 2t + 2t = 4t = π/2. Then t = π/8 and x = tan(π/8) = √2 − 1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-25", "question": "The range of (sin⁻¹x)³ + (cos⁻¹x)³, x ∈ [−1, 1], is:", "options": ["[π³/32, π³/8]", "[π³/32, 7π³/8]", "[0, 7π³/8]", "[π³/16, 7π³/8]"], "answer": 1, "explanation": "Let a = sin⁻¹x and b = π/2 − a. Then a³ + b³ = (a + b)³ − 3ab(a + b) = π³/8 − (3π/2)a(π/2 − a). The product a(π/2 − a) for a ∈ [−π/2, π/2] has maximum π²/16 (at a = π/4) and minimum −π²/2 (at a = −π/2). So the range is [π³/8 − 3π³/32, π³/8 + 3π³/4] = [π³/32, 7π³/8].", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "math-inverse-trig-26", "question": "Assertion (A): tan⁻¹2 + tan⁻¹3 = 3π/4.\nReason (R): tan⁻¹a + tan⁻¹b = tan⁻¹((a + b)/(1 − ab)) for all real a, b with ab ≠ 1.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: both angles lie in (π/4, π/2), so the sum is in (π/2, π) and its tangent is (2 + 3)/(1 − 6) = −1, giving 3π/4. R is false: the formula holds only when ab < 1; here it would give tan⁻¹(−1) = −π/4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-27", "question": "The value of cos⁻¹(cos 12) − sin⁻¹(sin 12) (12 in radians) is:", "options": ["8π − 24", "0", "24 − 8π", "24 − 7π"], "answer": 0, "explanation": "12 ∈ [3π, 4π], so cos⁻¹(cos 12) = 4π − 12 (which lies in [0, π]). 12 ∈ [7π/2, 9π/2], so sin⁻¹(sin 12) = 12 − 4π (which lies in [−π/2, π/2]). Difference: (4π − 12) − (12 − 4π) = 8π − 24.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-28", "question": "If x = cos(2 tan⁻¹(1/2)) and y = tan((1/2) sin⁻¹(3/5)), then:", "options": ["x = 3y²", "5x = 9y", "x + y = 1", "x = 2y"], "answer": 1, "explanation": "cos 2θ = (1 − tan²θ)/(1 + tan²θ) = (3/4)/(5/4) = 3/5, so x = 3/5. With sin φ = 3/5, cos φ = 4/5 and tan(φ/2) = sin φ/(1 + cos φ) = (3/5)/(9/5) = 1/3, so y = 1/3. Then 5x = 3 = 9y.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-29", "question": "Let f(x) = sin⁻¹(2x√(1 − x²)) for 1/√2 < x < 1. Then f′(√3/2) equals:", "options": ["4", "−2", "−4", "2"], "answer": 2, "explanation": "Put x = sin θ with θ ∈ (π/4, π/2). Then 2θ ∈ (π/2, π) and f = sin⁻¹(sin 2θ) = π − 2θ = π − 2 sin⁻¹x. So f′(x) = −2/√(1 − x²), and at x = √3/2 this is −2/(1/2) = −4. Using f = 2 sin⁻¹x gives the wrong sign.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "math-inverse-trig-30", "question": "The value of Σ (n = 1 to ∞) tan⁻¹(2n/(n⁴ + n² + 2)) is:", "options": ["π/4", "π/2", "π/3", "3π/4"], "answer": 0, "explanation": "2n/(n⁴ + n² + 2) = [(n² + n + 1) − (n² − n + 1)]/[1 + (n² + n + 1)(n² − n + 1)], since the product is n⁴ + n² + 1. So each term is tan⁻¹(n² + n + 1) − tan⁻¹(n² − n + 1), and the sum telescopes to lim tan⁻¹(N² + N + 1) − tan⁻¹1 = π/2 − π/4 = π/4.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-inverse-trig-31", "question": "The value of sin(cos⁻¹(3/5)) is:", "options": ["3/5", "3/4", "4/5", "5/4"], "answer": 2, "explanation": "Let θ = cos⁻¹(3/5), θ ∈ [0, π], so sin θ ≥ 0 and sin θ = √(1 − 9/25) = 4/5.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-32", "question": "The value of tan⁻¹(−1) + cos⁻¹(−1/√2) is:", "options": ["π", "0", "π/2", "−π/2"], "answer": 2, "explanation": "tan⁻¹(−1) = −π/4 (range (−π/2, π/2)) and cos⁻¹(−1/√2) = π − π/4 = 3π/4 (range [0, π]). Sum = π/2. Taking cos⁻¹(−1/√2) as −π/4, which lies outside [0, π], would wrongly give −π/2.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-33", "question": "The principal value of cot⁻¹(−1) is:", "options": ["−π/4", "3π/4", "π/4", "5π/4"], "answer": 1, "explanation": "The principal range of cot⁻¹ is (0, π), and cot⁻¹(−x) = π − cot⁻¹x, so cot⁻¹(−1) = π − π/4 = 3π/4. −π/4 lies outside (0, π).", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-34", "question": "The value of tan⁻¹(tan 3) (3 in radians) is:", "options": ["3", "3 − π", "π − 3", "3 − π/2"], "answer": 1, "explanation": "tan⁻¹(tan x) = x only for x ∈ (−π/2, π/2). Since 3 ∈ (π/2, 3π/2), subtract the period π: 3 − π ≈ −0.14, which lies in (−π/2, π/2).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-35", "question": "The value of cos(sin⁻¹(3/5) + sin⁻¹(5/13)) is:", "options": ["56/65", "63/65", "33/65", "16/65"], "answer": 2, "explanation": "cos(A + B) = cos A cos B − sin A sin B = (4/5)(12/13) − (3/5)(5/13) = 48/65 − 15/65 = 33/65. 63/65 is sin(A + B).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-36", "question": "The value of sin⁻¹(4/5) + 2 tan⁻¹(1/3) is:", "options": ["π/2", "π/3", "π/4", "π"], "answer": 0, "explanation": "2 tan⁻¹(1/3) = tan⁻¹((2/3)/(1 − 1/9)) = tan⁻¹(3/4), and sin⁻¹(4/5) = tan⁻¹(4/3). tan⁻¹(4/3) + tan⁻¹(3/4) = π/2 since the two are reciprocals of positive numbers.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-37", "question": "The value of tan((1/2) cos⁻¹(√5/3)) is:", "options": ["(3 − √5)/2", "(3 + √5)/2", "√5 − 2", "2/3"], "answer": 0, "explanation": "With cos θ = √5/3, tan(θ/2) = √((1 − cos θ)/(1 + cos θ)) = √((3 − √5)/(3 + √5)) = (3 − √5)/√(9 − 5) = (3 − √5)/2 (positive, since θ/2 ∈ [0, π/2]).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-38", "question": "If x, y, z > 0 and tan⁻¹x + tan⁻¹y + tan⁻¹z = π/2, then:", "options": ["x + y + z = 1", "x + y + z = xyz", "xyz = 1", "xy + yz + zx = 1"], "answer": 3, "explanation": "tan⁻¹x + tan⁻¹y = π/2 − tan⁻¹z, so (x + y)/(1 − xy) = cot(tan⁻¹z) = 1/z, giving xz + yz = 1 − xy, i.e. xy + yz + zx = 1. x + y + z = xyz is the condition for the sum to be π.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-39", "question": "The set of all x for which sin⁻¹x > cos⁻¹x is:", "options": ["[1/√2, 1]", "[−1, 1/√2)", "(0, 1]", "(1/√2, 1]"], "answer": 3, "explanation": "cos⁻¹x = π/2 − sin⁻¹x, so the inequality is sin⁻¹x > π/4, i.e. x > sin(π/4) = 1/√2, and x ≤ 1. At x = 1/√2 the two are equal, so it is excluded.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-40", "question": "For 0 < x < π/2, cot⁻¹[(√(1 + sin x) + √(1 − sin x))/(√(1 + sin x) − √(1 − sin x))] equals:", "options": ["2x", "π − x/2", "x/2", "π/2 − x/2"], "answer": 2, "explanation": "√(1 ± sin x) = cos(x/2) ± sin(x/2) for 0 < x < π/2. The ratio becomes 2cos(x/2)/(2sin(x/2)) = cot(x/2), and since x/2 ∈ (0, π/4) lies in (0, π), cot⁻¹(cot(x/2)) = x/2.", "difficulty": "hard", "source": "JEE Main · CBSE pattern"},
  {"id": "math-inverse-trig-41", "question": "The solution set of sin⁻¹(1 − x) − 2 sin⁻¹x = π/2 is:", "options": ["{−1/2, 0}", "{0, 1/2}", "{1/2}", "{0}"], "answer": 3, "explanation": "Put x = sin θ: 1 − x = sin(π/2 + 2θ) = cos 2θ = 1 − 2x², so 2x² − x = 0, x = 0 or 1/2. Check: x = 1/2 gives π/6 − π/3 = −π/6 ≠ π/2, so it is extraneous; x = 0 gives π/2. Only x = 0.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-42", "question": "The value of 4 tan⁻¹(1/5) − tan⁻¹(1/239) is:", "options": ["π/6", "π/3", "π/4", "π/2"], "answer": 2, "explanation": "2 tan⁻¹(1/5) = tan⁻¹(5/12); 4 tan⁻¹(1/5) = tan⁻¹((10/12)/(1 − 25/144)) = tan⁻¹(120/119). Then tan⁻¹(120/119) − tan⁻¹(1/239) = tan⁻¹[(120 × 239 − 119)/(119 × 239 + 120)] = tan⁻¹(28561/28561) = π/4 (Machin's formula).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-43", "question": "The range of f(x) = cot⁻¹(2x − x²), x real, is:", "options": ["[π/4, π)", "(0, π/4]", "(0, π)", "[π/4, 3π/4]"], "answer": 0, "explanation": "2x − x² = 1 − (x − 1)² takes every value in (−∞, 1]. cot⁻¹ is decreasing on R with range (0, π), so the image is [cot⁻¹1, lim at −∞) = [π/4, π).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-44", "question": "The identity 2 tan⁻¹x = sin⁻¹(2x/(1 + x²)) holds exactly for:", "options": ["|x| ≥ 1", "all real x", "x ≥ 0", "|x| ≤ 1"], "answer": 3, "explanation": "sin⁻¹ returns values in [−π/2, π/2], so 2 tan⁻¹x must lie there: |tan⁻¹x| ≤ π/4, i.e. |x| ≤ 1. For x > 1 the right side equals π − 2 tan⁻¹x instead.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-45", "question": "The value of tan⁻¹((1 + x)/(1 − x)) − tan⁻¹x at x = √3 is:", "options": ["5π/4", "π/4", "−3π/4", "−π/4"], "answer": 2, "explanation": "For x > 1, (1 + x)/(1 − x) < 0 and tan⁻¹((1 + x)/(1 − x)) = π/4 + tan⁻¹x − π. Check: tan⁻¹(−(2 + √3)) = −5π/12 and −5π/12 − π/3 = −3π/4. The tempting π/4 applies only for x < 1.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-46", "question": "If sin⁻¹x + sin⁻¹y + sin⁻¹z = 3π/2, then x¹⁰⁰ + y¹⁰⁰ + z¹⁰⁰ − 9/(x¹⁰¹ + y¹⁰¹ + z¹⁰¹) equals:", "options": ["3", "0", "−6", "6"], "answer": 1, "explanation": "Each sin⁻¹ is at most π/2, so the sum 3π/2 forces x = y = z = 1. The expression is 3 − 9/3 = 0.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-47", "question": "The solution set of tan⁻¹(x + 1) + tan⁻¹(x − 1) = tan⁻¹(8/31) is:", "options": ["{1/4}", "{1/4, −8}", "{−8}", "{−1/4, 8}"], "answer": 0, "explanation": "Taking tan: 2x/(2 − x²) = 8/31, so 4x² + 31x − 8 = 0, x = 1/4 or −8. For x = −8 the left side is tan⁻¹(−7) + tan⁻¹(−9), a negative angle near −2.89, not tan⁻¹(8/31) > 0. Only x = 1/4.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-48", "question": "For x ≠ 0, d/dx [tan⁻¹((√(1 + x²) − 1)/x)] equals:", "options": ["2/(1 + x²)", "1/(1 + x²)", "1/(2(1 + x²))", "x/(1 + x²)"], "answer": 2, "explanation": "Put x = tan θ (θ ∈ (−π/2, π/2), θ ≠ 0): (sec θ − 1)/tan θ = (1 − cos θ)/sin θ = tan(θ/2). So the function is θ/2 = (1/2) tan⁻¹x and its derivative is 1/(2(1 + x²)).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-49", "question": "Consider (principal values throughout):\n(1) cos⁻¹(cos x) = x for every x ∈ [0, π].\n(2) tan⁻¹(tan x) = x for every x ∈ (−π/2, π/2).\n(3) sin(sin⁻¹x) = x for every real x.\n(4) sin⁻¹x + cos⁻¹x = π/2 for every x ∈ [−1, 1].\nHow many of these statements are correct?", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) and (2) are true: on the principal branch the function undoes its inverse. (3) is false: sin⁻¹x is defined only for |x| ≤ 1, so sin(sin⁻¹2) is meaningless. (4) is true on the whole domain [−1, 1]. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-50", "question": "The number of real solutions of tan⁻¹√(x(x + 1)) + sin⁻¹√(x² + x + 1) = π/2 is:", "options": ["1", "0", "2", "4"], "answer": 2, "explanation": "Need x(x + 1) ≥ 0 for the first root and x² + x + 1 ≤ 1, i.e. x(x + 1) ≤ 0, for sin⁻¹. So x(x + 1) = 0: x = 0 or −1. Both give tan⁻¹0 + sin⁻¹1 = π/2. Two solutions.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-51", "question": "The solution set of cos⁻¹x − sin⁻¹x = cos⁻¹(x√3) is:", "options": ["{0}", "{0, 1/2}", "{1/2}", "{−1/2, 0, 1/2}"], "answer": 3, "explanation": "Let s = sin⁻¹x; the left side is π/2 − 2s, and cos(π/2 − 2s) = sin 2s = 2x√(1 − x²). Setting it equal to x√3: x = 0 or √(1 − x²) = √3/2, x = ±1/2. All three check: e.g. x = −1/2 gives 2π/3 + π/6 = 5π/6 = cos⁻¹(−√3/2).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-52", "question": "If cos⁻¹x + cos⁻¹y + cos⁻¹z = π, then x² + y² + z² + 2xyz equals:", "options": ["3", "0", "2", "1"], "answer": 3, "explanation": "cos⁻¹x + cos⁻¹y = π − cos⁻¹z, so taking cosines: xy − √(1 − x²)√(1 − y²) = −z. Then (xy + z)² = (1 − x²)(1 − y²), which simplifies to x² + y² + z² + 2xyz = 1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-53", "question": "For x > 1, the value of 2 tan⁻¹x + sin⁻¹(2x/(1 + x²)) is:", "options": ["4 tan⁻¹x", "π", "0", "π/2"], "answer": 1, "explanation": "For x > 1, 2 tan⁻¹x ∈ (π/2, π), while sin⁻¹ must return a value in [−π/2, π/2]; since sin(π − 2 tan⁻¹x) = 2x/(1 + x²), sin⁻¹(2x/(1 + x²)) = π − 2 tan⁻¹x. The sum is π. 4 tan⁻¹x uses the identity valid only for |x| ≤ 1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-54", "question": "For 0 < a < b, tan(π/4 + (1/2)cos⁻¹(a/b)) + tan(π/4 − (1/2)cos⁻¹(a/b)) equals:", "options": ["a/b", "2a/b", "b/a", "2b/a"], "answer": 3, "explanation": "With θ = (1/2)cos⁻¹(a/b), tan(π/4 + θ) + tan(π/4 − θ) = [(1 + t)² + (1 − t)²]/(1 − t²) = 2(1 + t²)/(1 − t²) = 2/cos 2θ, where t = tan θ. Since cos 2θ = a/b, the sum is 2b/a.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-55", "question": "For 0 < x < 1, let α = sin⁻¹(cos(sin⁻¹x)) and β = cos⁻¹(sin(cos⁻¹x)). Then tan α · tan β equals:", "options": ["x²", "1", "1 − x²", "x/√(1 − x²)"], "answer": 1, "explanation": "cos(sin⁻¹x) = √(1 − x²) and sin(cos⁻¹x) = √(1 − x²), so α = sin⁻¹√(1 − x²) and β = cos⁻¹√(1 − x²). Hence α + β = π/2 and tan α · tan β = tan α · cot α = 1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-56", "question": "The solution set of sin⁻¹(6x) + sin⁻¹(6√3 x) = −π/2 is:", "options": ["{−1/6}", "{1/12}", "{±1/12}", "{−1/12}"], "answer": 3, "explanation": "Write sin⁻¹(6√3x) = −π/2 − sin⁻¹(6x); taking sines, 6√3x = −cos(sin⁻¹6x) = −√(1 − 36x²), so x < 0 and 108x² = 1 − 36x², x² = 1/144, x = −1/12. Check: sin⁻¹(−1/2) + sin⁻¹(−√3/2) = −π/6 − π/3 = −π/2. x = 1/12 gives +π/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-57", "question": "The number of ordered pairs (x, y) of positive integers satisfying tan⁻¹(1/x) + tan⁻¹(1/y) = tan⁻¹(1/3) is:", "options": ["4", "2", "6", "3"], "answer": 0, "explanation": "Taking tan: (x + y)/(xy − 1) = 1/3, so xy − 3x − 3y − 1 = 0, i.e. (x − 3)(y − 3) = 10. Positive factor pairs give (4, 13), (5, 8), (8, 5), (13, 4); negative factor pairs make x or y ≤ 0. So 4 pairs.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-58", "question": "Assertion (A): cos(2 tan⁻¹(1/7)) = sin(4 tan⁻¹(1/3)).\nReason (R): cos 2θ = (1 − tan²θ)/(1 + tan²θ) and tan 2θ = 2tan θ/(1 − tan²θ).", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Using R: cos(2 tan⁻¹(1/7)) = (1 − 1/49)/(1 + 1/49) = 48/50 = 24/25. 2 tan⁻¹(1/3) = tan⁻¹(3/4), 4 tan⁻¹(1/3) = tan⁻¹((3/2)/(1 − 9/16)) = tan⁻¹(24/7), whose sine is 24/25. Both sides are 24/25, and R is exactly what proves it.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-59", "question": "The solution set of (tan⁻¹x)² − 3 tan⁻¹x + 2 ≥ 0 is:", "options": ["(−∞, tan 1]", "(−∞, tan 1] ∪ [tan 2, ∞)", "[tan 1, tan 2]", "R"], "answer": 0, "explanation": "With t = tan⁻¹x: (t − 1)(t − 2) ≥ 0 gives t ≤ 1 or t ≥ 2. But t < π/2 ≈ 1.57, so t ≥ 2 is impossible, leaving tan⁻¹x ≤ 1, i.e. x ≤ tan 1. The option with [tan 2, ∞) forgets the range of tan⁻¹ (tan 2 is even negative).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-inverse-trig-60", "question": "The solution set of sin⁻¹x + sin⁻¹(1 − x) = cos⁻¹x is:", "options": ["{0, 1/2}", "{1/2}", "{0}", "{0, 1}"], "answer": 0, "explanation": "Write sin⁻¹(1 − x) = cos⁻¹x − sin⁻¹x = π/2 − 2 sin⁻¹x; taking sines, 1 − x = cos(2 sin⁻¹x) = 1 − 2x², so x = 0 or 1/2. Both check: 0 + π/2 = π/2 and π/6 + π/6 = π/3. x = 1 gives π/2 + 0 ≠ 0.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-inverse-trig-61","question":"The value of sin⁻¹(sin 4) + cos⁻¹(cos 4) + tan⁻¹(tan 4) (angles in radians, principal values) is:","options":["2π − 4","0","π","12"],"answer":0,"explanation":"4 lies in (π, 3π/2). sin⁻¹(sin 4) = π − 4 (the value in [−π/2, π/2] with the same sine), cos⁻¹(cos 4) = 2π − 4 (in [0, π]) and tan⁻¹(tan 4) = 4 − π (in (−π/2, π/2)). The sum is (π − 4) + (2π − 4) + (4 − π) = 2π − 4; writing each as 4 gives the trap 12.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-inverse-trig-62","question":"The number of real solutions of sin⁻¹x = 2 tan⁻¹x is:","options":["1","3","2","0"],"answer":1,"explanation":"x = 0 works, and at x = ±1 both sides equal ±π/2, so x = −1, 0, 1 are solutions. For 0 < x < 1, put x = tan θ (0 < θ < π/4): sin(2θ) = 2x/(1 + x²) > x, so 2 tan⁻¹x > sin⁻¹x and there is no other root; by oddness the same holds on (−1, 0). So exactly 3 solutions (students who stop at x = 0 answer 1).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-inverse-trig-63","question":"The value of Σ (r = 1 to ∞) tan⁻¹(2ʳ⁻¹/(1 + 2²ʳ⁻¹)) is:","options":["π/2","π/3","π/4","tan⁻¹2"],"answer":2,"explanation":"Since (2ʳ − 2ʳ⁻¹)/(1 + 2ʳ·2ʳ⁻¹) = 2ʳ⁻¹/(1 + 2²ʳ⁻¹), each term is tan⁻¹(2ʳ) − tan⁻¹(2ʳ⁻¹). The partial sums telescope to tan⁻¹(2ⁿ) − tan⁻¹1 → π/2 − π/4 = π/4.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-inverse-trig-64","question":"The domain of f(x) = sin⁻¹((x² + 1)/(2x)) is:","options":["[−1, 1]","{1}","the empty set","{−1, 1}"],"answer":3,"explanation":"Need −1 ≤ (x² + 1)/(2x) ≤ 1, i.e. x² + 1 ≤ 2|x|, i.e. (|x| − 1)² ≤ 0. This forces |x| = 1, so the domain is {−1, 1}: at x = −1 the argument is −1 and at x = 1 it is 1, both allowed (forgetting the negative case gives {1}).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-inverse-trig-65","question":"The range of f(x) = cos⁻¹((1 − x²)/(1 + x²)), x real, is:","options":["[0, π)","[0, π]","(0, π)","[0, π/2]"],"answer":0,"explanation":"The argument (1 − x²)/(1 + x²) = −1 + 2/(1 + x²) takes every value in (−1, 1] — it equals 1 at x = 0 but never reaches −1. So cos⁻¹ of it takes every value in [0, π), with π excluded.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "math-inverse-trig-66", "question": "For every x < 0, cos⁻¹((1 − x²)/(1 + x²)) equals:", "options": ["2 tan⁻¹x", "−2 tan⁻¹x", "π − 2 tan⁻¹x", "π + 2 tan⁻¹x"], "answer": 1, "explanation": "Put x = tan θ with −π/2 < θ < 0: the argument is cos 2θ = cos(−2θ), and −2θ ∈ (0, π), so cos⁻¹(cos 2θ) = −2θ = −2 tan⁻¹x. The formula 2 tan⁻¹x holds only for x ≥ 0 and would give a negative value here, which cos⁻¹ can never take.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"math-inverse-trig-67","question":"Let A = sin⁻¹(sin 2), B = cos⁻¹(cos 2) and C = tan⁻¹(tan 2) (2 in radians). Then:","options":["A > B > C","B > C > A","B > A > C","A = B > C"],"answer":2,"explanation":"2 lies in (π/2, π). A = π − 2 ≈ 1.14, B = 2 (already in [0, π]) and C = 2 − π ≈ −1.14. So B > A > C; A = B = C = 2 is the trap of ignoring principal ranges.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-inverse-trig-68","question":"The equation sin⁻¹(sin x) = x − 2π holds exactly for x in:","options":["[−π/2, π/2]","[π/2, 3π/2]","[2π, 5π/2]","[3π/2, 5π/2]"],"answer":3,"explanation":"sin⁻¹(sin x) = x − 2π requires x − 2π ∈ [−π/2, π/2] (then sin(x − 2π) = sin x and the value lies in the principal range). This gives x ∈ [3π/2, 5π/2]; [2π, 5π/2] misses the half where x − 2π is negative.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-inverse-trig-69","question":"The value of tan⁻¹(1/3) + tan⁻¹(1/5) + tan⁻¹(1/7) + tan⁻¹(1/8) is:","options":["π/4","π/2","tan⁻¹(7/9)","π/3"],"answer":0,"explanation":"tan⁻¹(1/3) + tan⁻¹(1/5) = tan⁻¹((8/15)/(14/15)) = tan⁻¹(4/7); adding tan⁻¹(1/7) gives tan⁻¹((5/7)/(45/49)) = tan⁻¹(7/9); adding tan⁻¹(1/8) gives tan⁻¹((65/72)/(65/72)) = tan⁻¹1 = π/4. All partial products are below 1, so no π correction is needed (tan⁻¹(7/9) is the sum of only the first three).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-inverse-trig-70","question":"The identity cos⁻¹(4x³ − 3x) = 3 cos⁻¹x holds exactly for x in:","options":["[−1, 1]","[1/2, 1]","[−1/2, 1/2]","[−1, −1/2]"],"answer":1,"explanation":"Put x = cos θ with θ ∈ [0, π]; then 4x³ − 3x = cos 3θ and cos⁻¹(cos 3θ) = 3θ only when 3θ ∈ [0, π], i.e. θ ∈ [0, π/3]. That means x = cos θ ∈ [1/2, 1]; for other x the left side is 2π − 3θ or 3θ − 2π.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-inverse-trig-71","question":"The real solution of tan⁻¹x + 2 cot⁻¹x = 2π/3 is:","options":["x = 1/√3","x = −√3","x = √3","x = 1"],"answer":2,"explanation":"For every real x, cot⁻¹x = π/2 − tan⁻¹x (principal values, cot⁻¹ ∈ (0, π)). So the equation is π − tan⁻¹x = 2π/3, i.e. tan⁻¹x = π/3 and x = √3.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "math-inverse-trig-72", "question": "The value of cos⁻¹(−1/2) − 2 sin⁻¹(1/2) + 3 cos⁻¹(−1/√2) − 4 tan⁻¹(−1) is:", "options": ["19π/12", "35π/12", "π/3", "43π/12"], "answer": 3, "explanation": "cos⁻¹(−1/2) = 2π/3, sin⁻¹(1/2) = π/6, cos⁻¹(−1/√2) = 3π/4 and tan⁻¹(−1) = −π/4. So the value is 2π/3 − π/3 + 9π/4 + π = π/3 + 13π/4 = 43π/12.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"math-inverse-trig-73","question":"If x, y ≥ 0 and sin⁻¹x + sin⁻¹y = π/2, the greatest value of xy is:","options":["1/2","1","1/4","√2/2"],"answer":0,"explanation":"sin⁻¹y = π/2 − sin⁻¹x = cos⁻¹x, so y = sin(cos⁻¹x) = √(1 − x²), i.e. x² + y² = 1. Then xy ≤ (x² + y²)/2 = 1/2, attained at x = y = 1/√2.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "math-inverse-trig-74", "question": "The value of d/dx [sin⁻¹(2x/(1 + x²))] at x = 2 is:", "options": ["2/5", "−2/5", "4/5", "−4/5"], "answer": 1, "explanation": "For x > 1, sin⁻¹(2x/(1 + x²)) = π − 2 tan⁻¹x (with x = tan θ, θ ∈ (π/4, π/2), 2θ exceeds π/2 and sin⁻¹(sin 2θ) = π − 2θ). Its derivative is −2/(1 + x²) = −2/5 at x = 2; using 2 tan⁻¹x blindly gives the sign-wrong 2/5.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-inverse-trig-75","question":"The area enclosed between the graph of y = sin⁻¹(sin x) and the x-axis for 0 ≤ x ≤ 2π is:","options":["π²/4","π²","π²/2","π"],"answer":2,"explanation":"y = sin⁻¹(sin x) is the triangular wave: y = x on [0, π/2], π − x on [π/2, 3π/2] and x − 2π on [3π/2, 2π]. It forms two triangles of base π and height π/2 (one above, one below the axis), each of area π²/4, so the total area is π²/2 (the signed integral would be 0).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-inverse-trig-76", "question": "How many of the following are correct (principal values)?\n(1) tan⁻¹(1/2) + tan⁻¹(1/3) = π/4.\n(2) sin⁻¹(3/5) + sin⁻¹(4/5) = π/2.\n(3) cot⁻¹(−x) = −cot⁻¹x for every real x.\n(4) sec⁻¹x + cosec⁻¹x = π/2 for every |x| ≥ 1.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) (1/2 + 1/3)/(1 − 1/6) = 1, true. (2) sin⁻¹(4/5) = cos⁻¹(3/5), so the sum is sin⁻¹(3/5) + cos⁻¹(3/5) = π/2, true. (3) false: since cot⁻¹ takes values in (0, π), cot⁻¹(−x) = π − cot⁻¹x. (4) true, since sec⁻¹x = cos⁻¹(1/x) and cosec⁻¹x = sin⁻¹(1/x). Three are correct.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-inverse-trig-77", "question": "The set of all real x for which tan⁻¹x > cot⁻¹x is:", "options": ["(−∞, −1) ∪ (1, ∞)", "(−1, 1)", "(0, ∞)", "(1, ∞)"], "answer": 3, "explanation": "With principal values cot⁻¹x = π/2 − tan⁻¹x for all real x, the inequality is 2 tan⁻¹x > π/2, i.e. tan⁻¹x > π/4, so x > 1. For x < 0, tan⁻¹x is negative while cot⁻¹x lies in (π/2, π). Writing cot⁻¹x = tan⁻¹(1/x) (valid only for x > 0) wrongly adds (−∞, −1).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-inverse-trig-78","question":"The range of f(x) = sin⁻¹x · cos⁻¹x, x ∈ [−1, 1], is:","options":["[−π²/2, π²/16]","[0, π²/16]","[−π²/4, π²/16]","[−π²/2, π²/4]"],"answer":0,"explanation":"With s = sin⁻¹x ∈ [−π/2, π/2], f = s(π/2 − s), a downward parabola in s with vertex at s = π/4, where f = π²/16. On the interval the least value is at s = −π/2: (−π/2)(π) = −π²/2. So the range is [−π²/2, π²/16].","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-inverse-trig-79","question":"If x is real and cos⁻¹x = tan⁻¹x, then sin(cos⁻¹x) equals:","options":["(√5 + 1)/2","(√5 − 1)/2","1/√2","√((√5 − 1)/2)"],"answer":1,"explanation":"Let θ = cos⁻¹x = tan⁻¹x; then θ ∈ (0, π/2) and cos θ = tan θ, so sin θ = cos²θ = 1 − sin²θ. Hence sin²θ + sin θ − 1 = 0 and sin θ = (√5 − 1)/2 (the positive root); √((√5 − 1)/2) is x itself.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-inverse-trig-80", "question": "The value of lim (x → ∞) x·[π/4 − tan⁻¹(x/(x + 1))] is:", "options": ["0", "1", "1/2", "1/4"], "answer": 2, "explanation": "π/4 − tan⁻¹(x/(x + 1)) = tan⁻¹((1 − x/(x + 1))/(1 + x/(x + 1))) = tan⁻¹(1/(2x + 1)). Since tan⁻¹u ≈ u for small u, the limit is lim x/(2x + 1) = 1/2.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-inverse-trig-81","question":"For π/4 < x < 3π/4, the value of sin⁻¹((sin x + cos x)/√2) is:","options":["x + π/4","π/4 − x","x − π/4","3π/4 − x"],"answer":3,"explanation":"(sin x + cos x)/√2 = sin(x + π/4), and x + π/4 ∈ (π/2, π) lies outside [−π/2, π/2]. So sin⁻¹(sin(x + π/4)) = π − (x + π/4) = 3π/4 − x; x + π/4 is the branch-ignoring trap.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-inverse-trig-82","question":"For x < −1, tan⁻¹((x − 1)/(x + 1)) equals:","options":["tan⁻¹x + 3π/4","tan⁻¹x − π/4","tan⁻¹x − 5π/4","π/4 − tan⁻¹x"],"answer":0,"explanation":"tan(tan⁻¹x − π/4) = (x − 1)/(1 + x), so the answer is tan⁻¹x − π/4 + kπ, whichever value lies in (−π/2, π/2). For x < −1, tan⁻¹x ∈ (−π/2, −π/4), so tan⁻¹x − π/4 ∈ (−3π/4, −π/2) is out of range and we must add π: tan⁻¹x + 3π/4. Check x = −2: tan⁻¹3 ≈ 1.249 = −1.107 + 2.356.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-inverse-trig-83","question":"For every x < 0, cot⁻¹x − tan⁻¹(1/x) equals (principal values, cot⁻¹ taking values in (0, π)):","options":["0","π","π/2","−π"],"answer":1,"explanation":"For x < 0, cot⁻¹x lies in (π/2, π), while tan⁻¹(1/x) lies in (−π/2, 0); both have cotangent x, so they differ by π: cot⁻¹x = π + tan⁻¹(1/x). The identity cot⁻¹x = tan⁻¹(1/x), giving 0, holds only for x > 0.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-inverse-trig-84", "question": "The identity 2 cos⁻¹x = sin⁻¹(2x√(1 − x²)) holds exactly for x in:", "options": ["[0, 1]", "[−1/√2, 1/√2]", "[1/√2, 1]", "[−1, −1/√2]"], "answer": 2, "explanation": "Put x = cos θ with θ ∈ [0, π]; then √(1 − x²) = sin θ and the right side is sin⁻¹(sin 2θ), which equals 2θ only when 2θ ∈ [0, π/2] (2θ ≥ 0 here). So θ ∈ [0, π/4] and x ∈ [1/√2, 1]; the interval [−1/√2, 1/√2] belongs to the identity 2 sin⁻¹x = sin⁻¹(2x√(1 − x²)) instead.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-inverse-trig-85", "question": "The sum of all real x satisfying (sin⁻¹x)² + (cos⁻¹x)² = 5π²/36 is:", "options": ["√3/2", "1", "(√3 − 1)/2", "(1 + √3)/2"], "answer": 3, "explanation": "With s = sin⁻¹x and cos⁻¹x = π/2 − s: 2s² − πs + π²/4 = 5π²/36, i.e. 2s² − πs + π²/9 = 0, so s = (π ± π/3)/4 = π/3 or π/6. Both lie in [−π/2, π/2], giving x = √3/2 and 1/2, whose sum is (1 + √3)/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-inverse-trig-86","question":"The value of cos(tan⁻¹(3/4)) is:","options":["4/5","3/5","3/4","5/4"],"answer":0,"explanation":"If tan θ = 3/4 with θ in (0, π/2), the right triangle has sides 3, 4, 5, so cos θ = 4/5.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-inverse-trig-87","question":"The value of tan⁻¹(1) + cot⁻¹(1) + sin⁻¹(1) is:","options":["3π/4","π/2","5π/4","π"],"answer":3,"explanation":"tan⁻¹1 = π/4, cot⁻¹1 = π/4 and sin⁻¹1 = π/2. The sum is π/4 + π/4 + π/2 = π.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-inverse-trig-88","question":"The domain of f(x) = √(cos⁻¹x − π/3) is:","options":["[1/2, 1]","[−1, 1/2]","[−1, √3/2]","[−1, 1]"],"answer":1,"explanation":"We need −1 ≤ x ≤ 1 and cos⁻¹x ≥ π/3. Since cos⁻¹ is decreasing, cos⁻¹x ≥ π/3 means x ≤ cos(π/3) = 1/2. So the domain is [−1, 1/2].","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-inverse-trig-89","question":"The value of tan(cos⁻¹(4/5) + tan⁻¹(2/3)) is:","options":["6/17","17/6","17/12","1/6"],"answer":1,"explanation":"cos⁻¹(4/5) = tan⁻¹(3/4). Then tan(A + B) = (3/4 + 2/3)/(1 − (3/4)(2/3)) = (17/12)/(1/2) = 17/6.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-inverse-trig-90","question":"The range of f(x) = tan⁻¹(x² + 1), x real, is:","options":["(0, π/2)","[π/4, π/2]","(−π/2, π/2)","[π/4, π/2)"],"answer":3,"explanation":"x² + 1 takes every value in [1, ∞). As tan⁻¹ is increasing, f takes values from tan⁻¹1 = π/4 (at x = 0) up to, but never reaching, π/2. Range: [π/4, π/2).","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-inverse-trig-91","question":"For every x < 0, tan⁻¹x + tan⁻¹(1/x) equals:","options":["−π/2","π/2","0","−π/4"],"answer":0,"explanation":"For x > 0 the sum is π/2. Both functions are odd, so for x < 0 the sum is −(π/2) = −π/2. It is not 'always π/2'.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-inverse-trig-92","question":"For 0 < x < 1, sin(cot⁻¹(tan(cos⁻¹x))) equals:","options":["√(1 − x²)","1/x","x","x/√(1 − x²)"],"answer":2,"explanation":"Let cos⁻¹x = θ ∈ (0, π/2); tan θ = √(1 − x²)/x. Then cot⁻¹ of this is an angle φ in (0, π/2) with cot φ = √(1 − x²)/x, i.e. sin φ = x. So the expression is x.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-inverse-trig-93","question":"The value of cos(2 cos⁻¹(1/3) + sin⁻¹(1/3)) is:","options":["2√2/3","−1/3","1/3","−2√2/3"],"answer":3,"explanation":"2cos⁻¹x + sin⁻¹x = cos⁻¹x + (cos⁻¹x + sin⁻¹x) = cos⁻¹x + π/2. So the value is cos(cos⁻¹(1/3) + π/2) = −sin(cos⁻¹(1/3)) = −√(1 − 1/9) = −2√2/3.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-94","question":"The range of f(x) = sin⁻¹x + tan⁻¹x is:","options":["[−π/2, π/2]","(−π, π)","[−3π/4, 3π/4]","[−π/4, π/4]"],"answer":2,"explanation":"f is defined on [−1, 1], and both terms are increasing, so f is increasing. Its range runs from f(−1) = −π/2 − π/4 = −3π/4 to f(1) = 3π/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-95","question":"The solution set of tan⁻¹(x + 3) − tan⁻¹(x − 3) = tan⁻¹(3/4) is:","options":["{4}","{−4, 4}","{−4}","{−2√2, 2√2}"],"answer":1,"explanation":"The left side always lies in (0, π) and its tangent is 6/(1 + x² − 9) = 6/(x² − 8) whenever x² ≠ 8. Setting 6/(x² − 8) = 3/4 gives x² = 16. Both x = 4 (tan⁻¹7 − tan⁻¹1) and x = −4 (tan⁻¹(−1) − tan⁻¹(−7)) give the acute angle tan⁻¹(3/4), so both work.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-96","question":"For 1/2 ≤ x ≤ 1, the value of cos⁻¹x + cos⁻¹(x/2 + √(3 − 3x²)/2) is:","options":["π/3","2π/3","π/6","2 cos⁻¹x − π/3"],"answer":0,"explanation":"Put x = cos θ with θ ∈ [0, π/3]. Then x/2 + (√3/2)√(1 − x²) = cos θ cos(π/3) + sin θ sin(π/3) = cos(θ − π/3) = cos(π/3 − θ). As π/3 − θ ∈ [0, π/3], cos⁻¹ returns π/3 − θ, so the sum is θ + π/3 − θ = π/3.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-97","question":"The value of ∫ cos⁻¹x dx from x = −1 to 1 is:","options":["π","π/2","2","0"],"answer":0,"explanation":"cos⁻¹(−x) = π − cos⁻¹x, so pairing x with −x makes the integrand average to π/2. Over an interval of length 2 the integral is 2 × π/2 = π. No integration by parts is needed.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-98","question":"The number of solutions of cos⁻¹(cos x) = x/2 in [0, 4π] is:","options":["3","2","1","4"],"answer":1,"explanation":"cos⁻¹(cos x) is the triangle wave x on [0, π], 2π − x on [π, 2π], x − 2π on [2π, 3π], 4π − x on [3π, 4π]. Equating with x/2: x = 0 in the first piece, x = 4π/3 in the second; the third gives x = 4π and the fourth x = 8π/3, both outside their pieces. So there are 2 solutions.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-99","question":"tan⁻¹(1/4) + tan⁻¹(2/9) equals:","options":["(1/2) sin⁻¹(3/5)","π/6","(1/2) cos⁻¹(3/5)","π/4"],"answer":2,"explanation":"tan of the sum is (1/4 + 2/9)/(1 − 1/18) = (17/36)/(17/18) = 1/2, so the sum is tan⁻¹(1/2). If cos θ = 3/5 then tan(θ/2) = sin θ/(1 + cos θ) = (4/5)/(8/5) = 1/2, so tan⁻¹(1/2) = (1/2) cos⁻¹(3/5).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-100","question":"For 0 < x < 1, tan⁻¹x + tan⁻¹((1 − x)/(1 + x)) equals:","options":["π/2","2 tan⁻¹x","π/4 − tan⁻¹x","π/4"],"answer":3,"explanation":"(1 − x)/(1 + x) = tan(π/4 − θ) where x = tan θ, θ ∈ (0, π/4). Since π/4 − θ lies in (0, π/4), tan⁻¹ returns it exactly, and the sum is θ + π/4 − θ = π/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-101","question":"If sin⁻¹x + sin⁻¹y = 2π/3 and cos⁻¹x − cos⁻¹y = π/3, then (x, y) is:","options":["(1, 1/2)","(√3/2, 1)","(1/2, 1)","(1/2, √3/2)"],"answer":2,"explanation":"From sin⁻¹ = π/2 − cos⁻¹, the first equation gives cos⁻¹x + cos⁻¹y = π − 2π/3 = π/3. Adding the second: 2cos⁻¹x = 2π/3, so cos⁻¹x = π/3 and cos⁻¹y = 0. Hence x = 1/2, y = 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-102","question":"The set of all x for which sin⁻¹x > sin⁻¹(x²) is:","options":["(0, 1)","[−1, 0)","(−1, 1)","[0, 1]"],"answer":0,"explanation":"Both sides need |x| ≤ 1. sin⁻¹ is strictly increasing, so the inequality is x > x², i.e. x(1 − x) > 0, which gives 0 < x < 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-103","question":"The value of lim (n → ∞) (1/n) Σ (k = 1 to n) tan⁻¹(k/n) is:","options":["π/4","π/4 + (1/2) ln 2","(1/2) ln 2","π/4 − (1/2) ln 2"],"answer":3,"explanation":"It is the Riemann sum for ∫₀¹ tan⁻¹x dx. By parts: [x tan⁻¹x]₀¹ − ∫₀¹ x/(1 + x²) dx = π/4 − (1/2) ln 2 ≈ 0.439.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-104","question":"The value of Σ (k = 1 to ∞) tan⁻¹(2/k²) is:","options":["π/2","3π/4","π/4","π"],"answer":1,"explanation":"2/k² = [(k + 1) − (k − 1)]/[1 + (k + 1)(k − 1)], so each term is tan⁻¹(k + 1) − tan⁻¹(k − 1). Cancelling in steps of two leaves lim [tan⁻¹(n + 1) + tan⁻¹n] − tan⁻¹0 − tan⁻¹1 = π − π/4 = 3π/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-inverse-trig-105","question":"The area of the region bounded by y = sin⁻¹x, y = cos⁻¹x and the y-axis is:","options":["√2 − 1","2 − √2","π/(2√2) − 1","1/√2"],"answer":1,"explanation":"The curves meet at x = 1/√2, and for 0 ≤ x ≤ 1/√2, cos⁻¹x ≥ sin⁻¹x. Area = ∫₀^(1/√2) (π/2 − 2 sin⁻¹x) dx. Using ∫ sin⁻¹x dx = x sin⁻¹x + √(1 − x²): the area is π/(2√2) − 2[π/(4√2) + 1/√2 − 1] = 2 − √2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-106","question":"The value of Σ (k = 1 to ∞) cot⁻¹(k² + 3/4) is:","options":["π/4","tan⁻¹(1/2)","π/2","tan⁻¹2"],"answer":3,"explanation":"cot⁻¹(k² + 3/4) = tan⁻¹[1/(1 + (k − 1/2)(k + 1/2))] = tan⁻¹(k + 1/2) − tan⁻¹(k − 1/2). The series telescopes to π/2 − tan⁻¹(1/2) = tan⁻¹2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-107","question":"The value of ∫ [sin⁻¹(sin x) + cos⁻¹(cos x)] dx from x = 0 to π is:","options":["3π²/4","π²/2","π²","π²/4"],"answer":0,"explanation":"On [0, π/2] both terms equal x, so the integrand is 2x. On [π/2, π], sin⁻¹(sin x) = π − x and cos⁻¹(cos x) = x, so the integrand is π. The integral is π²/4 + π·(π/2) = 3π²/4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-108","question":"Let f(x) = tan⁻¹((1 + x)/(1 − x)) for x ≠ 1. Then f(2) − f(0) equals:","options":["tan⁻¹2","π − tan⁻¹2","tan⁻¹2 − π","−tan⁻¹2"],"answer":2,"explanation":"For x < 1, f(x) = π/4 + tan⁻¹x, but for x > 1 the angle π/4 + tan⁻¹x exceeds π/2, so f(x) = π/4 + tan⁻¹x − π. Hence f(2) − f(0) = (tan⁻¹2 − 3π/4) − π/4 = tan⁻¹2 − π (directly: tan⁻¹(−3) − π/4).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-109","question":"The set of all x in [0, 2π] satisfying sin⁻¹(sin x) = cos⁻¹(cos x) is:","options":["[0, π/2]","[0, π/2] ∪ [3π/2, 2π]","{0, π/2, 2π}","[0, π/2] ∪ {2π}"],"answer":3,"explanation":"On [0, π/2] both sides equal x. On [π/2, π]: π − x = x only at π/2. On [π, 3π/2]: π − x ≤ 0 < 2π − x, no solution. On [3π/2, 2π]: x − 2π = 2π − x only at x = 2π. So the set is [0, π/2] ∪ {2π}.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-110","question":"The range of f(x) = sin⁻¹x + 2 tan⁻¹x + x² + 4x + 1 is:","options":["[−π − 2, π + 4]","[−2, 6]","[−π − 2, π + 6]","[−π, π + 6]"],"answer":2,"explanation":"On (−1, 1), f′(x) = 1/√(1 − x²) + 2/(1 + x²) + 2x + 4 > 0 because 2x + 4 > 2. So f is increasing on its domain [−1, 1], with f(−1) = −π/2 − π/2 + 1 − 4 + 1 = −π − 2 and f(1) = π/2 + π/2 + 6 = π + 6.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-111","question":"The real solution of sin⁻¹x = cos⁻¹(x²) is:","options":["(√5 − 1)/2","√((√5 − 1)/2)","1/√2","√((√5 + 1)/2)"],"answer":1,"explanation":"The right side is in [0, π/2], so x ≥ 0. Taking cosine: x² = cos(sin⁻¹x) = √(1 − x²), so x⁴ + x² − 1 = 0 and x² = (√5 − 1)/2. Hence x = √((√5 − 1)/2) ≈ 0.786, the only solution.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-112","question":"The area of the region bounded by y = tan⁻¹x, y = cot⁻¹x and the y-axis is:","options":["ln 2","π/4","1 − ln 2","π/2 − ln 2"],"answer":0,"explanation":"The curves meet where tan⁻¹x = π/4, i.e. x = 1, and cot⁻¹x ≥ tan⁻¹x on [0, 1]. Area = ∫₀¹ (π/2 − 2 tan⁻¹x) dx = π/2 − 2(π/4 − (1/2) ln 2) = ln 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-113","question":"How many of the following are correct (principal values)?\n(1) sin⁻¹(cos x) = π/2 − x for every x in [0, π].\n(2) tan⁻¹(tan x) = x − π for every x in (π/2, 3π/2).\n(3) cos⁻¹(−x) = π − cos⁻¹x for every x in [−1, 1].\n(4) cot⁻¹(−x) = −cot⁻¹x for every real x.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(1) cos x = sin(π/2 − x) and π/2 − x ∈ [−π/2, π/2], so it holds. (2) x − π ∈ (−π/2, π/2) has the same tangent, so it holds. (3) is a standard identity. (4) is false: cot⁻¹ takes values in (0, π), and cot⁻¹(−x) = π − cot⁻¹x. Three are correct.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-114","question":"The value of ∫ sin⁻¹(2x/(1 + x²)) dx from x = 0 to 1 is:","options":["π/4 − (1/2) ln 2","π/2 − ln 2","π/2 + ln 2","ln 2"],"answer":1,"explanation":"For 0 ≤ x ≤ 1, sin⁻¹(2x/(1 + x²)) = 2 tan⁻¹x (the identity fails only for |x| > 1). So the integral is 2∫₀¹ tan⁻¹x dx = 2(π/4 − (1/2) ln 2) = π/2 − ln 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-115","question":"The value of ∫ x·sin⁻¹x dx from x = 0 to 1 is:","options":["π/4","1/2","π/8","π/4 − 1/2"],"answer":2,"explanation":"Put x = sin θ: the integral becomes ∫₀^(π/2) θ sin θ cos θ dθ = (1/2)∫₀^(π/2) θ sin 2θ dθ. By parts, ∫₀^(π/2) θ sin 2θ dθ = [−θ cos 2θ/2]₀^(π/2) + [sin 2θ/4]₀^(π/2) = π/4. So the value is π/8.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-116","question":"For 1/2 < x < 1, the derivative of f(x) = sin⁻¹(3x − 4x³) is:","options":["3/√(1 − x²)","3/(1 + x²)","−3/(1 + x²)","−3/√(1 − x²)"],"answer":3,"explanation":"With x = sin θ, 3x − 4x³ = sin 3θ. For 1/2 < x < 1, θ ∈ (π/6, π/2) and 3θ ∈ (π/2, 3π/2), so sin⁻¹(sin 3θ) = π − 3θ. Hence f(x) = π − 3 sin⁻¹x and f′(x) = −3/√(1 − x²): the naive answer 3/√(1 − x²) has the wrong sign.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-117","question":"The value of Σ (r = 1 to ∞) tan⁻¹(8r/(r⁴ − 2r² + 5)) is:","options":["π/2","3π/4","π − tan⁻¹(1/2)","π − tan⁻¹2"],"answer":2,"explanation":"With A = (r + 1)²/2 and B = (r − 1)²/2: A − B = 2r and 1 + AB = (r⁴ − 2r² + 5)/4, so the term is tan⁻¹A − tan⁻¹B. Cancelling in steps of two leaves lim[tan⁻¹((n + 1)²/2) + tan⁻¹(n²/2)] − tan⁻¹0 − tan⁻¹(1/2) = π − tan⁻¹(1/2).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-118","question":"The number of real solutions of tan⁻¹x + tan⁻¹(1 − x) = tan⁻¹(4/3) is:","options":["1","2","0","infinitely many"],"answer":0,"explanation":"For every real x, x(1 − x) ≤ 1/4 < 1, so the left side equals tan⁻¹[(x + 1 − x)/(1 − x + x²)] = tan⁻¹[1/(x² − x + 1)]. Setting 1/(x² − x + 1) = 4/3 gives x² − x + 1/4 = 0, i.e. (x − 1/2)² = 0. So x = 1/2 is the only solution (a double root, not two).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-inverse-trig-119","question":"For x > 0, the greatest value of tan⁻¹x − tan⁻¹(x/4) is:","options":["π/4","tan⁻¹(3/5)","tan⁻¹(1/2)","tan⁻¹(3/4)"],"answer":3,"explanation":"For x > 0 the difference is in (0, π/2) and its tangent is (3x/4)/(1 + x²/4) = 3x/(4 + x²) = 3/(x + 4/x) ≤ 3/4 by AM–GM, with equality at x = 2. So the greatest value is tan⁻¹(3/4).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
